def me():
    identity = get_jwt_identity()
    user = _find_user_by_id(identity)
    if user is None:
        return jsonify({"error": "user not found"}), 404
    return jsonify(_public_user(user)), 200


def current_user():
    from flask_jwt_extended import get_jwt_identity

    identity = get_jwt_identity()
    if identity is None:
