@bp.put("/<int:task_id>")
@jwt_required()
def update_task(task_id):
    user_id = get_jwt_identity()
    user = get_db().execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
    row = _find_task(task_id)
